def make_ndarray_with_pad_optimized_v1(x, pad, dtype, max_len=None):
    """Optimized using numpy's row_stack."""
    if max_len is None:
        max_len = max(map(len, x), default=0)

    if len(x) == 0:
        return np.empty((0, max_len), dtype=dtype)

    # Use numpy's row_stack with padding
    # Convert each list to a padded numpy array
    padded_rows = []
    for item in x:
        if len(item) == max_len:
            padded_rows.append(np.array(item, dtype=dtype))
        else:
            # Create padded array efficiently
            row = np.empty(max_len, dtype=dtype)
            row[:] = pad
            row[:len(item)] = item
            padded_rows.append(row)

    return np.row_stack(padded_rows)

def make_ndarray_with_pad_optimized_v2(x, pad, dtype, max_len=None):
    """Optimized using single allocation and vectorized operations."""
    if max_len is None:
        max_len = max(map(len, x), default=0)

    if len(x) == 0:
        return np.empty((0, max_len), dtype=dtype)

    # Single allocation
    result = np.full((len(x), max_len), pad, dtype=dtype)

    # Use vectorized operations where possible
    # For small lists, the overhead of vectorization might not be worth it
    # But we can still optimize by batching similar-length lists

    # Group by length to minimize slicing operations
    from collections import defaultdict
    length_groups = defaultdict(list)
    for i, item in enumerate(x):
        length_groups[len(item)].append((i, item))

    # Process each group
    for length, items in length_groups.items():
        if length == 0:
            continue
        indices = [idx for idx, _ in items]
        values = [item for _, item in items]
        result[indices, :length] = values

