            all_match = all(np.array_equal(first_result, r) for r in results.values())
            print(f"  All match: {all_match}")

            if all_match:
                # Benchmark
                times = {}
                for name, func in implementations:
                    start = time.perf_counter()
                    for _ in range(1000):
                        func(test_data, 0, np.int64)
                    end = time.perf_counter()
                    times[name] = (end - start) * 1000

                # Print times
                for name, t in times.items():
                    print(f"  {name}: {t:.2f} ms")

                # Find best
                best_name = min(times, key=times.get)
                best_time = times[best_name]
                print(f"  Best: {best_name} ({best_time:.2f} ms)")

                # Show speedup
                orig_time = times["Original"]
                if best_time > 0:
                    speedup = orig_time / best_time
                    if speedup > 1:
                        print(f"  Speedup: {speedup:.2f}x")
                    else:
                        print(f"  Slowdown: {1/speedup:.2f}x")

if __name__ == "__main__":
    test_all_implementations()

